import type { HashAlgorithm } from './HashAlgorithm';
import type { HashSeed } from './HashSeed';

const MAX_UINT32 = 0xffffffffn;
const MAX_UINT64 = 0xffffffffffffffffn;

/** Keep seed validation ahead of native initialization and any file work. */
export default function serializeSeed(algorithm: HashAlgorithm, seed: HashSeed = 0): string {
  if (typeof seed !== 'number' && typeof seed !== 'bigint') {
    throw new TypeError('Expected a number or bigint seed');
  }
  if (typeof seed === 'number' && !Number.isSafeInteger(seed)) {
    throw new RangeError('Seed must be a safe integer; use bigint for larger seeds');
  }
  const value = BigInt(seed);
  const maximum = algorithm === 'xxh32' ? MAX_UINT32 : MAX_UINT64;
  if (value < 0n || value > maximum) {
    throw new RangeError(`Seed must be an unsigned ${algorithm === 'xxh32' ? 32 : 64}-bit integer`);
  }
  return value.toString();
}

import type { HashAlgorithm } from './HashAlgorithm';
import type { FileHashOptions, HashOptions } from './HashOptions';
import type { HashOutput } from './HashOutput';
import type { HashSeed } from './HashSeed';
import { validateHashOutput } from './convertHashOutput';
import serializeSeed from './serializeSeed';

interface ParsedHashOptions {
  seed: string;
  output: HashOutput;
  signal?: AbortSignal;
}

/** Snapshot and validate options before native loading or borrowing input bytes. */
export default function parseHashOptions(
  value: HashSeed | HashOptions<HashOutput> | FileHashOptions<HashOutput> | undefined,
  algorithm: HashAlgorithm,
  { allowSignal = false }: { allowSignal?: boolean } = {},
): ParsedHashOptions {
  let seed: HashSeed | undefined;
  let output: HashOutput = 'hex';
  let signal: AbortSignal | undefined;
  if (value === undefined || typeof value === 'number' || typeof value === 'bigint') {
    seed = value;
  } else {
    if (typeof value !== 'object' || value === null || Array.isArray(value)) {
      throw new TypeError('Expected a seed or hash options object');
    }
    const prototype: unknown = Object.getPrototypeOf(value);
    if (prototype !== null && Object.getPrototypeOf(prototype) !== null) {
      throw new TypeError('Expected a seed or hash options object');
    }
    for (const key of Reflect.ownKeys(value)) {
      if (key !== 'seed' && key !== 'output' && !(allowSignal && key === 'signal')) {
        throw new TypeError(`Unknown hash option: ${String(key)}`);
      }
    }
    seed = value.seed;
    const requested = value.output;
    if (requested !== undefined) {
      validateHashOutput(requested);
      output = requested;
    }
    if (allowSignal) {
      signal = (value as FileHashOptions<HashOutput>).signal;
      // RN's AbortSignal polyfill is not necessarily an instance of the host's
      // global class. Validate its event contract instead of using instanceof.
      if (
        signal !== undefined &&
        (typeof signal !== 'object' ||
          signal === null ||
          typeof signal.aborted !== 'boolean' ||
          typeof signal.addEventListener !== 'function' ||
          typeof signal.removeEventListener !== 'function')
      ) {
        throw new TypeError('Expected an AbortSignal');
      }
    }
  }
  return { seed: serializeSeed(algorithm, seed), output, signal };
}

import type { HashAlgorithm } from './HashAlgorithm';
import type { HashInput } from './HashInput';
import type { HashOptions } from './HashOptions';
import type { HashOutput, HashResult } from './HashOutput';
import type { HashSeed } from './HashSeed';
import convertHashOutput from './convertHashOutput';
import getFileHasher from './getFileHasher';
import normalizeHashInput from './normalizeHashInput';
import parseHashOptions from './parseHashOptions';
import type { FileHasher } from './specs/FileHasher.nitro';

export interface HashFunction {
  (input: HashInput, seed?: HashSeed): string;
  <T extends HashOutput>(input: HashInput, options: HashOptions<T> & { output: T }): HashResult<T>;
  (input: HashInput, options: HashOptions<'hex'> | undefined): string;
  <T extends HashOutput>(
    input: HashInput,
    options?: HashSeed | HashOptions<T>,
  ): HashResult<T | 'hex'>;
}

/** Public helpers deliberately hide the private, transport-oriented Nitro API. */
export default function createHashFunction(algorithm: HashAlgorithm): HashFunction {
  let hashString: FileHasher['hashString'] | undefined;
  let hashBuffer: FileHasher['hashBuffer'] | undefined;
  const hash = (input: HashInput, options?: HashSeed | HashOptions<HashOutput>) => {
    const parsed = parseHashOptions(options, algorithm);
    const normalized = normalizeHashInput(input);
    if (typeof normalized === 'string') {
      if (!hashString) {
        const hasher = getFileHasher();
        hashString = hasher.hashString.bind(hasher);
      }
      return convertHashOutput(hashString(normalized, algorithm, parsed.seed), parsed.output);
    }
    if (!hashBuffer) {
      const hasher = getFileHasher();
      hashBuffer = hasher.hashBuffer.bind(hasher);
    }
    return convertHashOutput(
      hashBuffer(
        normalized.buffer,
        normalized.byteOffset,
        normalized.byteLength,
        algorithm,
        parsed.seed,
      ),
      parsed.output,
    );
  };
  return hash as HashFunction;
}
